begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(576);

-- Additive physical scope and legacy coexistence.
select has_table('public',t,t||' exists')from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select has_table('public',t,'legacy '||t||' remains')from(values('shifts'),('payments'),('debt_payments'))x(t);
select ok('public.shifts'::regclass<>'public.shifts_v2'::regclass,'legacy and V2 shifts remain distinct');
select ok('public.payments'::regclass<>'public.payments_v2'::regclass,'legacy and V2 payments remain distinct');
select ok('public.debt_payments'::regclass<>'public.debt_payments_v2'::regclass,'legacy and V2 debt payments remain distinct');
select ok(not exists(select 1 from public.cash_movements),'cash ledger has no automatic backfill');
select ok(not exists(select 1 from public.supplier_payments),'supplier payments have no automatic backfill');

-- Registry and profiles are exact after 0016.
select is((select count(*)from permissions),54::bigint,'permission registry 54');
select is((select count(*)from permissions where critical),10::bigint,'critical permissions 10');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000101'),54::bigint,'owner profile 54');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000102'),16::bigint,'seller profile remains 16');
select set_eq($$select code from permissions where critical$$,$$select * from(values('purchases.reverse'),('sales.reverse'),('sales.discount.override'),('debts.limit.override'),('cash.move.override'),('support.access.approve'),('debts.reverse'),('debts.write_off'),('settlements.close'),('settlements.reverse'))x(code)$$,'critical permission set exact');
select ok(exists(select 1 from permissions where code='cash.view'and module='cash'and not critical),'cash.view is noncritical cash permission');
select ok(exists(select 1 from permissions where code='settlements.reverse'and module='settlements'and critical),'settlements.reverse is critical');
select ok(exists(select 1 from permission_profile_permissions x join permissions p on p.id=x.permission_id where x.permission_profile_id='00000000-0000-0000-0000-000000000101'and p.code=c),'owner receives '||c)from(values('cash.view'),('settlements.reverse'))x(c);
select ok(not exists(select 1 from permission_profile_permissions x join permissions p on p.id=x.permission_id where x.permission_profile_id='00000000-0000-0000-0000-000000000102'and p.code=c),'seller denied '||c)from(values('cash.view'),('settlements.reverse'))x(c);

-- Every location/cash column exists (62 distinct schema facts).
with expected(t,c)as(values
 ('cash_movements','id'),('cash_movements','organization_id'),('cash_movements','branch_id'),('cash_movements','register_id'),('cash_movements','shift_id'),('cash_movements','movement_type'),('cash_movements','amount_delta'),('cash_movements','currency_code'),('cash_movements','business_date'),('cash_movements','source_type'),('cash_movements','source_id'),('cash_movements','reason'),('cash_movements','device_id'),('cash_movements','local_operation_id'),('cash_movements','reversal_of_id'),('cash_movements','command_id'),('cash_movements','approval_request_id'),('cash_movements','created_by'),('cash_movements','created_at'),
 ('shift_cash_counts','id'),('shift_cash_counts','organization_id'),('shift_cash_counts','branch_id'),('shift_cash_counts','register_id'),('shift_cash_counts','shift_id'),('shift_cash_counts','line_number'),('shift_cash_counts','denomination_value'),('shift_cash_counts','quantity'),('shift_cash_counts','counted_amount'),('shift_cash_counts','currency_code'),('shift_cash_counts','command_id'),('shift_cash_counts','counted_by'),('shift_cash_counts','created_at'),
 ('supplier_payments','id'),('supplier_payments','organization_id'),('supplier_payments','branch_id'),('supplier_payments','register_id'),('supplier_payments','counterparty_id'),('supplier_payments','shift_id'),('supplier_payments','document_number'),('supplier_payments','business_date'),('supplier_payments','total_amount'),('supplier_payments','currency_code'),('supplier_payments','status'),('supplier_payments','device_id'),('supplier_payments','local_operation_id'),('supplier_payments','client_created_at'),('supplier_payments','posted_by'),('supplier_payments','posted_at'),('supplier_payments','reversal_of_id'),('supplier_payments','command_id'),('supplier_payments','approval_request_id'),('supplier_payments','created_at'),
 ('shifts_v2','business_date'),('shifts_v2','currency_code'),('shifts_v2','expected_cash_amount'),('shifts_v2','open_command_id'),('shifts_v2','close_command_id'),('shifts_v2','close_approval_id'),('payments_v2','supplier_payment_id'))
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name=t and column_name=c),t||'.'||c||' exists')from expected;

-- Exact data types are stable.
with expected(t,c,u)as(values
 ('cash_movements','id','uuid'),('cash_movements','organization_id','uuid'),('cash_movements','branch_id','uuid'),('cash_movements','register_id','uuid'),('cash_movements','shift_id','uuid'),('cash_movements','movement_type','text'),('cash_movements','amount_delta','numeric'),('cash_movements','currency_code','bpchar'),('cash_movements','business_date','date'),('cash_movements','source_type','text'),('cash_movements','source_id','uuid'),('cash_movements','reason','text'),('cash_movements','device_id','uuid'),('cash_movements','local_operation_id','uuid'),('cash_movements','reversal_of_id','uuid'),('cash_movements','command_id','uuid'),('cash_movements','approval_request_id','uuid'),('cash_movements','created_by','uuid'),('cash_movements','created_at','timestamptz'),
 ('shift_cash_counts','id','uuid'),('shift_cash_counts','organization_id','uuid'),('shift_cash_counts','branch_id','uuid'),('shift_cash_counts','register_id','uuid'),('shift_cash_counts','shift_id','uuid'),('shift_cash_counts','line_number','int4'),('shift_cash_counts','denomination_value','numeric'),('shift_cash_counts','quantity','int4'),('shift_cash_counts','counted_amount','numeric'),('shift_cash_counts','currency_code','bpchar'),('shift_cash_counts','command_id','uuid'),('shift_cash_counts','counted_by','uuid'),('shift_cash_counts','created_at','timestamptz'),
 ('supplier_payments','id','uuid'),('supplier_payments','organization_id','uuid'),('supplier_payments','branch_id','uuid'),('supplier_payments','register_id','uuid'),('supplier_payments','counterparty_id','uuid'),('supplier_payments','shift_id','uuid'),('supplier_payments','document_number','text'),('supplier_payments','business_date','date'),('supplier_payments','total_amount','numeric'),('supplier_payments','currency_code','bpchar'),('supplier_payments','status','text'),('supplier_payments','device_id','uuid'),('supplier_payments','local_operation_id','uuid'),('supplier_payments','client_created_at','timestamptz'),('supplier_payments','posted_by','uuid'),('supplier_payments','posted_at','timestamptz'),('supplier_payments','reversal_of_id','uuid'),('supplier_payments','command_id','uuid'),('supplier_payments','approval_request_id','uuid'),('supplier_payments','created_at','timestamptz'),
 ('shifts_v2','business_date','date'),('shifts_v2','currency_code','bpchar'),('shifts_v2','expected_cash_amount','numeric'),('shifts_v2','open_command_id','uuid'),('shifts_v2','close_command_id','uuid'),('shifts_v2','close_approval_id','uuid'),('payments_v2','supplier_payment_id','uuid'))
select ok(exists(select 1 from pg_attribute a where a.attrelid=format('public.%I',t)::regclass and a.attname=c and a.atttypid=u::regtype),t||'.'||c||' type '||u)from expected;

-- Required/nullability contract: all listed fields are NOT NULL.
with expected(t,c)as(values
 ('cash_movements','id'),('cash_movements','organization_id'),('cash_movements','branch_id'),('cash_movements','register_id'),('cash_movements','shift_id'),('cash_movements','movement_type'),('cash_movements','amount_delta'),('cash_movements','currency_code'),('cash_movements','business_date'),('cash_movements','source_type'),('cash_movements','source_id'),('cash_movements','device_id'),('cash_movements','local_operation_id'),('cash_movements','command_id'),('cash_movements','created_by'),('cash_movements','created_at'),
 ('shift_cash_counts','id'),('shift_cash_counts','organization_id'),('shift_cash_counts','branch_id'),('shift_cash_counts','register_id'),('shift_cash_counts','shift_id'),('shift_cash_counts','line_number'),('shift_cash_counts','denomination_value'),('shift_cash_counts','quantity'),('shift_cash_counts','counted_amount'),('shift_cash_counts','currency_code'),('shift_cash_counts','command_id'),('shift_cash_counts','counted_by'),('shift_cash_counts','created_at'),
 ('supplier_payments','id'),('supplier_payments','organization_id'),('supplier_payments','branch_id'),('supplier_payments','register_id'),('supplier_payments','counterparty_id'),('supplier_payments','shift_id'),('supplier_payments','document_number'),('supplier_payments','business_date'),('supplier_payments','total_amount'),('supplier_payments','currency_code'),('supplier_payments','status'),('supplier_payments','device_id'),('supplier_payments','local_operation_id'),('supplier_payments','client_created_at'),('supplier_payments','posted_by'),('supplier_payments','posted_at'),('supplier_payments','command_id'),('supplier_payments','created_at'))
select ok((select attnotnull from pg_attribute where attrelid=format('public.%I',t)::regclass and attname=c),t||'.'||c||' is required')from expected;
select ok(not(select attnotnull from pg_attribute where attrelid='public.cash_movements'::regclass and attname=c),'cash_movements.'||c||' nullable')from(values('reason'),('reversal_of_id'),('approval_request_id'))x(c);
select ok(not(select attnotnull from pg_attribute where attrelid='public.supplier_payments'::regclass and attname=c),'supplier_payments.'||c||' nullable')from(values('reversal_of_id'),('approval_request_id'))x(c);
select ok(not(select attnotnull from pg_attribute where attrelid='public.shifts_v2'::regclass and attname=c),'historical shifts_v2.'||c||' nullable-compatible')from(values('business_date'),('currency_code'),('expected_cash_amount'),('open_command_id'),('close_command_id'),('close_approval_id'))x(c);

-- Defaults, constraints, foreign keys and indexes.
select ok((select adbin is not null from pg_attrdef d join pg_attribute a on a.attrelid=d.adrelid and a.attnum=d.adnum where d.adrelid=format('public.%I',t)::regclass and a.attname=c),t||'.'||c||' has default')from(values
 ('cash_movements','id'),('cash_movements','created_at'),('shift_cash_counts','id'),('shift_cash_counts','created_at'),('supplier_payments','id'),('supplier_payments','status'),('supplier_payments','posted_at'),('supplier_payments','created_at'))x(t,c);
select ok(exists(select 1 from pg_constraint where conrelid=format('public.%I',t)::regclass and conname=n),t||'.'||n)from(values
 ('cash_movements','cash_movements_type_check'),('cash_movements','cash_movements_source_check'),('cash_movements','cash_movements_amount_check'),('cash_movements','cash_movements_currency_check'),('cash_movements','cash_movements_reason_check'),
 ('shift_cash_counts','shift_cash_counts_line_check'),('shift_cash_counts','shift_cash_counts_denomination_check'),('shift_cash_counts','shift_cash_counts_quantity_check'),('shift_cash_counts','shift_cash_counts_amount_check'),('shift_cash_counts','shift_cash_counts_currency_check'),
 ('supplier_payments','supplier_payments_number_check'),('supplier_payments','supplier_payments_amount_check'),('supplier_payments','supplier_payments_currency_check'),('supplier_payments','supplier_payments_status_check'),
 ('shifts_v2','shifts_v2_currency_check'),('shifts_v2','shifts_v2_expected_cash_check'),('payments_v2','payments_v2_source_check'))x(t,n);
select ok(exists(select 1 from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=any(c.conkey)where c.contype='f'and c.conrelid=format('public.%I',t)::regclass and a.attname=col and c.confrelid=format('public.%I',target)::regclass),t||'.'||col||' -> '||target)from(values
 ('cash_movements','organization_id','organizations'),('cash_movements','branch_id','branches'),('cash_movements','register_id','registers'),('cash_movements','shift_id','shifts_v2'),('cash_movements','device_id','devices_v2'),('cash_movements','reversal_of_id','cash_movements'),('cash_movements','command_id','command_log'),('cash_movements','approval_request_id','approval_requests'),('cash_movements','created_by','organization_memberships'),
 ('shift_cash_counts','organization_id','organizations'),('shift_cash_counts','branch_id','branches'),('shift_cash_counts','register_id','registers'),('shift_cash_counts','shift_id','shifts_v2'),('shift_cash_counts','command_id','command_log'),('shift_cash_counts','counted_by','organization_memberships'),
 ('supplier_payments','organization_id','organizations'),('supplier_payments','branch_id','branches'),('supplier_payments','register_id','registers'),('supplier_payments','counterparty_id','counterparties'),('supplier_payments','shift_id','shifts_v2'),('supplier_payments','device_id','devices_v2'),('supplier_payments','posted_by','organization_memberships'),('supplier_payments','reversal_of_id','supplier_payments'),('supplier_payments','command_id','command_log'),('supplier_payments','approval_request_id','approval_requests'),
 ('payments_v2','supplier_payment_id','supplier_payments'),('shifts_v2','open_command_id','command_log'),('shifts_v2','close_command_id','command_log'),('shifts_v2','close_approval_id','approval_requests'))x(t,col,target);
select ok(exists(select 1 from pg_indexes where schemaname='public'and tablename=t and indexname=n),n||' exists')from(values
 ('cash_movements','cash_movements_one_opening'),('cash_movements','cash_movements_payment_source_key'),('cash_movements','cash_movements_one_reversal'),('cash_movements','cash_movements_manual_operation'),('cash_movements','cash_movements_shift_journal_idx'),('cash_movements','cash_movements_org_branch_date_idx'),('cash_movements','cash_movements_source_idx'),('cash_movements','cash_movements_command_idx'),
 ('shift_cash_counts','shift_cash_counts_command_idx'),('supplier_payments','supplier_payments_one_reversal'),('supplier_payments','supplier_payments_journal_idx'),('supplier_payments','supplier_payments_counterparty_idx'),('supplier_payments','supplier_payments_shift_idx'),('payments_v2','payments_v2_supplier_payment_idx'))x(t,n);

-- Trigger inventory and immutable ledgers.
select ok(exists(select 1 from pg_trigger where tgrelid=format('public.%I',t)::regclass and tgname=n and not tgisinternal),n||' installed')from(values
 ('cash_movements','v2_cash_movements_context'),('cash_movements','v2_cash_movements_guard'),('cash_movements','v2_cash_movements_append_only'),
 ('shift_cash_counts','v2_shift_cash_counts_context'),('shift_cash_counts','v2_shift_cash_counts_guard'),('shift_cash_counts','v2_shift_cash_counts_append_only'),
 ('supplier_payments','v2_supplier_payments_context'),('supplier_payments','v2_supplier_payments_guard'),('supplier_payments','v2_supplier_payments_delete'),
 ('shifts_v2','v2_shifts_guard'),('shift_totals','v2_shift_totals_guard'),('payments_v2','v2_payments_guard'),
 ('settlement_entries','v2_settlement_entries_guard'),('settlement_entries','v2_settlement_entries_guard_supplier'))x(t,n);

-- RLS and grants: SELECT only through policies/RPC, never browser writes.
select ok((select relrowsecurity from pg_class where oid=format('public.%I',t)::regclass),t||' RLS enabled')from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select ok(not has_table_privilege('anon',format('public.%I',t),'SELECT,INSERT,UPDATE,DELETE'),'anon denied '||t)from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select ok(has_table_privilege('authenticated',format('public.%I',t),'SELECT'),'authenticated SELECT via RLS '||t)from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select ok(not has_table_privilege('authenticated',format('public.%I',t),'INSERT,UPDATE,DELETE'),'browser writes denied '||t)from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename=t and cmd='SELECT'),'SELECT policy '||t)from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);
select ok(not exists(select 1 from pg_policies where schemaname='public'and tablename=t and cmd in('INSERT','UPDATE','DELETE')),'no browser write policy '||t)from(values('cash_movements'),('shift_cash_counts'),('supplier_payments'))x(t);

-- Public API and internal helper inventory.
select ok(to_regprocedure(sig)is not null,sig||' exists')from(values
 ('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,uuid)'),('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)'),
 ('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)'),('public.v2_reverse_cash_movement(uuid,uuid,uuid,uuid,uuid,jsonb)'),
 ('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)'),('public.v2_reverse_supplier_payment(uuid,uuid,text,uuid,uuid,uuid,jsonb)'),
 ('public.v2_close_shift(uuid,uuid,numeric,uuid)'),('public.v2_close_shift(uuid,uuid,jsonb,jsonb,uuid,uuid)'),
 ('public.v2_cash_journal(uuid,uuid,uuid)'),('public.v2_shift_reconciliation(uuid)'),('public.v2_supplier_payment_journal(uuid,uuid,uuid)'),('public.v2_supplier_payment_journal(uuid,uuid,uuid,character)'),
 ('public.v2_lock_operation_scope(uuid,uuid,uuid)'),('public.v2_lock_register_shift_scope(uuid,uuid,uuid)'),('public.v2_cash_context_required()'),('public.v2_cash_append_only()'),('public.v2_supplier_payment_context_required()'),
 ('public.v2_guard_cash_movement()'),('public.v2_guard_shift_cash_count()'),('public.v2_guard_supplier_payment()'),('public.v2_guard_supplier_settlement_entry()'),
 ('public.v2_recompute_shift_payment_totals(uuid)'),('public.v2_expected_physical_cash(uuid)'),('public.v2_require_cash_drawer_capacity(uuid,numeric)'),('public.v2_validate_payment_cash_graph(uuid)'),('public.v2_cash_count_total(uuid,uuid)'),('public.v2_validate_shift_close_snapshot(uuid,uuid)'),('public.v2_append_cash_movement_for_payment(uuid,uuid)'),('public.v2_require_open_sales_shift(uuid,uuid,uuid,uuid,uuid,uuid)'))x(sig);
select ok(has_function_privilege('authenticated',sig,'EXECUTE'),'authenticated executes '||sig)from(values
 ('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,uuid)'),('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)'),
 ('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)'),('public.v2_reverse_cash_movement(uuid,uuid,uuid,uuid,uuid,jsonb)'),
 ('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)'),('public.v2_reverse_supplier_payment(uuid,uuid,text,uuid,uuid,uuid,jsonb)'),
 ('public.v2_close_shift(uuid,uuid,numeric,uuid)'),('public.v2_close_shift(uuid,uuid,jsonb,jsonb,uuid,uuid)'),('public.v2_cash_journal(uuid,uuid,uuid)'),('public.v2_shift_reconciliation(uuid)'),('public.v2_supplier_payment_journal(uuid,uuid,uuid)'),('public.v2_supplier_payment_journal(uuid,uuid,uuid,character)'))x(sig);
select ok(not has_function_privilege(role_name,sig,'EXECUTE'),role_name||' denied internal '||sig)from(values('public'),('anon'),('authenticated'))r(role_name)cross join(values
 ('public.v2_lock_operation_scope(uuid,uuid,uuid)'),('public.v2_lock_register_shift_scope(uuid,uuid,uuid)'),('public.v2_cash_context_required()'),('public.v2_cash_append_only()'),('public.v2_supplier_payment_context_required()'),('public.v2_guard_cash_movement()'),('public.v2_guard_shift_cash_count()'),('public.v2_guard_supplier_payment()'),('public.v2_guard_supplier_settlement_entry()'),('public.v2_recompute_shift_payment_totals(uuid)'),('public.v2_expected_physical_cash(uuid)'),('public.v2_require_cash_drawer_capacity(uuid,numeric)'),('public.v2_validate_payment_cash_graph(uuid)'),('public.v2_cash_count_total(uuid,uuid)'),('public.v2_validate_shift_close_snapshot(uuid,uuid)'),('public.v2_append_cash_movement_for_payment(uuid,uuid)'),('public.v2_require_open_sales_shift(uuid,uuid,uuid,uuid,uuid,uuid)'))f(sig);

-- Distinct definition-level contracts (single-session concurrency evidence included).
select ok(position(lower(needle)in lower(pg_get_functiondef(sig::regprocedure)))>0,description)from(values
 ('public.v2_lock_operation_scope(uuid,uuid,uuid)','market-pos-operation:','operation lock uses isolated deterministic prefix'),('public.v2_lock_operation_scope(uuid,uuid,uuid)','V2_OPERATION_SCOPE_REQUIRED','operation lock rejects null identity'),('public.v2_lock_register_shift_scope(uuid,uuid,uuid)','pg_advisory_xact_lock','register scope uses transaction advisory lock'),('public.v2_lock_register_shift_scope(uuid,uuid,uuid)','V2_REGISTER_SHIFT_SCOPE_MISMATCH','lock validates exact register scope'),
 ('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)','v2_lock_register_shift_scope','canonical open takes central lock'),('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)','V2_SHIFT_ALREADY_OPEN','canonical open has stable contention error'),('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)','OpeningCashRecorded','open emits opening event'),('public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,character,date,uuid)','shift_totals','open creates three totals'),
 ('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)','v2_lock_register_shift_scope','manual writer takes central lock'),('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)','cash.move.override','correction requires override'),('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)','V2_CASH_MOVEMENT_INPUT_INVALID','manual input error stable'),('public.v2_record_cash_movement(uuid,uuid,text,numeric,character,date,text,uuid,uuid)','CashMovementPosted','manual command emits event'),
 ('public.v2_reverse_cash_movement(uuid,uuid,uuid,uuid,uuid,jsonb)','v2_lock_register_shift_scope','manual reversal takes central lock'),('public.v2_reverse_cash_movement(uuid,uuid,uuid,uuid,uuid,jsonb)','V2_CASH_MANUAL_REVERSAL_FORBIDDEN','only manual movements reverse here'),('public.v2_reverse_cash_movement(uuid,uuid,uuid,uuid,uuid,jsonb)','CashMovementReversed','manual reversal emits event'),
 ('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)','v2_lock_register_shift_scope','supplier writer takes register lock'),('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)','v2_lock_settlement_scope','supplier writer takes settlement lock'),('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)','V2_SUPPLIER_PAYMENT_EXCEEDS_PAYABLE','supplier prepayment denied'),('public.v2_record_supplier_payment(uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamp with time zone,jsonb)','SupplierPaymentRecorded','supplier record emits event'),
 ('public.v2_reverse_supplier_payment(uuid,uuid,text,uuid,uuid,uuid,jsonb)','settlements.reverse','supplier reversal permission exact'),('public.v2_reverse_supplier_payment(uuid,uuid,text,uuid,uuid,uuid,jsonb)','v2_use_approved_command','supplier reversal uses exact approval'),('public.v2_reverse_supplier_payment(uuid,uuid,text,uuid,uuid,uuid,jsonb)','SupplierPaymentReversed','supplier reversal emits event'),
