select lives_ok($$select v2_create_purchase_draft('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000016501','00000000-0000-0000-0000-000000016901','P16-USD',current_date,'USD',null,'00000000-0000-0000-0000-000000017911')$$,'USD payable purchase draft created');
select lives_ok($$select v2_upsert_purchase_line(null,(select id from purchase_documents where document_number='P16-USD'),1,'00000000-0000-0000-0000-000000016904','00000000-0000-0000-0000-000000016903',1,1,10,null,'P16-USD-LOT')$$,'USD payable purchase line created');
select lives_ok($$select v2_post_purchase((select id from purchase_documents where document_number='P16-USD'),'00000000-0000-0000-0000-000000017912','{}')$$,'USD payable purchase posted');
select lives_ok($$select v2_record_supplier_payment('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000017601',(select id from shifts_v2 where register_id='00000000-0000-0000-0000-000000017601'and status='open'),'00000000-0000-0000-0000-000000016901','SP16-USD',current_date,'USD','00000000-0000-0000-0000-000000017701','00000000-0000-0000-0000-000000017913',now(),jsonb_build_array(jsonb_build_object('method','card','amount',-5)))$$,'USD supplier payment succeeds');
select ok(not exists(select 1 from v2_supplier_payment_journal('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000016901','UZS')where currency_code<>'UZS'),'UZS journal returns only UZS rows');
select is((select count(*)from v2_supplier_payment_journal('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000016901','USD')),1::bigint,'USD journal returns exact USD row');
select throws_ok($$select * from v2_supplier_payment_journal('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000016901')$$,'P0001','V2_SUPPLIER_PAYMENT_CURRENCY_REQUIRED','compatibility journal rejects two currencies');
select throws_ok($$select v2_record_supplier_payment('00000000-0000-0000-0000-000000016101','00000000-0000-0000-0000-000000016401','00000000-0000-0000-0000-000000017601',(select id from shifts_v2 where register_id='00000000-0000-0000-0000-000000017601'and status='open'),'00000000-0000-0000-0000-000000017901','SP16-NOROLE',current_date,'USD','00000000-0000-0000-0000-000000017701','00000000-0000-0000-0000-000000017914',now(),jsonb_build_array(jsonb_build_object('method','card','amount',-1)))$$,'P0001','V2_SUPPLIER_ROLE_HISTORY_REQUIRED','party without supplier role history denied');
reset role;
select is((select count(*)from supplier_payments where document_number='SP16-NOROLE'),0::bigint,'role-history failure leaves no supplier payment');
select is((select count(*)from command_log where local_operation_id='00000000-0000-0000-0000-000000017914'),0::bigint,'role-history failure leaves no command');

select * from finish();
rollback;
